private static MetaEncodingDetector partition(List<EncodingDetector> all, List<EncodingDetector> base) {
    MetaEncodingDetector meta = null;
    for (EncodingDetector d : all) {
        if (d instanceof MetaEncodingDetector) {
            if (meta == null) {
                meta = (MetaEncodingDetector) d;
            } else {
                LOG.warn("Multiple MetaEncodingDetectors found; ignoring {}", d.getClass().getName());
            }
        } else {
            base.add(d);
        }
    }
    return meta;
}
